///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Cal16
 * @description Cal16 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Cal16 = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Cal16"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Cal16", unresolved: "action:self_submit:tx_fn_Cal16" };
};

/**
 * @method
 * @name tx_fn_Cal17
 * @description Cal17 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Cal17 = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Cal17"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Cal17", unresolved: "action:self_submit:tx_fn_Cal17" };
};

/**
 * @method
 * @name tx_fn_ExcelDown
 * @description Excel Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ExcelDown = async function () {
    try { return await $c.data.downFile("/bizspt/excelDown.jsp", "", ($c.util.getComponent("dma_ExcelDownReq") ? $c.util.getComponent("dma_ExcelDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name cal16
 * @description cal16 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal16 = async function () {
    let ISU_CD = $c.util.getComponent('ipt_ISU_CD').getValue(); if (ISU_CD === null) { ISU_CD = ''; }
    if (ISU_CD === "") {
        await $c.win.alert("[종목코드]을 선택하세요.");
        ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').setFocus ? $c.util.getComponent('ipt_ISU_CD').setFocus() : ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').focus ? $c.util.getComponent('ipt_ISU_CD').focus() : console.warn('[sdd] focus 대상 미해결: ipt_ISU_CD')));
        return;
    }
    if (($c.util.getComponent('ipt_dividendPerStock').getValue() === null ? '' : String($c.util.getComponent('ipt_dividendPerStock').getValue())) === '') {
        await $c.win.alert("[주당배당금]을 입력하세요.");
        $c.util.getComponent("ipt_dividendPerStock").focus();
        return;
    }
    if (($c.util.getComponent('cal_standartDateOfDividend').getValue() === null ? '' : String($c.util.getComponent('cal_standartDateOfDividend').getValue())) === '') {
        await $c.win.alert("[주주명부폐쇄일 2매매거래일 전]을 입력하세요.");
        $c.util.getComponent("cal_standartDateOfDividend").focus();
        return;
    }
    $c.util.setCookie("ISU_CD", ISU_CD, 1);
    $c.util.setCookie("COM_NM", $c.util.getComponent('ipt_COM_NM').getValue(), 1);
    $c.util.getComponent("dma_basicInfo").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_basicInfo").set("COM_NM", encodeURI($c.util.getComponent('ipt_COM_NM').getValue()));
    $c.util.getComponent('dma_Cal16Req').set('method', "processCalculateRelatedDisclosure16");
    await scwin.tx_fn_Cal16();
};

/**
 * @method
 * @name cal17
 * @description cal17 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal17 = async function () {
    let ISU_CD = $c.util.getComponent('ipt_ISU_CD').getValue(); if (ISU_CD === null) { ISU_CD = ''; }
    if (ISU_CD === "") {
        await $c.win.alert("[종목코드]을 선택하세요.");
        ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').setFocus ? $c.util.getComponent('ipt_ISU_CD').setFocus() : ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').focus ? $c.util.getComponent('ipt_ISU_CD').focus() : console.warn('[sdd] focus 대상 미해결: ipt_ISU_CD')));
        return;
    }
    if (($c.util.getComponent('ipt_dispositionTotal').getValue() === null ? '' : String($c.util.getComponent('ipt_dispositionTotal').getValue())) === '') {
        await $c.win.alert("[배당총액]을 입력하세요.");
        $c.util.getComponent("ipt_dispositionTotal").focus();
        return;
    }
    if (($c.util.getComponent('ipt_clearProfit').getValue() === null ? '' : String($c.util.getComponent('ipt_clearProfit').getValue())) === '') {
        await $c.win.alert("[당기순이익]을 입력하세요.");
        $c.util.getComponent("ipt_clearProfit").focus();
        return;
    }
    $c.util.setCookie("ISU_CD", ISU_CD, 1);
    $c.util.setCookie("COM_NM", $c.util.getComponent('ipt_COM_NM').getValue(), 1);
    $c.util.getComponent("dma_basicInfo").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_basicInfo").set("COM_NM", encodeURI($c.util.getComponent('ipt_COM_NM').getValue()));
    $c.util.getComponent('dma_Cal16Req').set('method', "processCalculateRelatedDisclosure17");
    await scwin.tx_fn_Cal17();
};

/**
 * @method
 * @name checkNum
 * @description check Num 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkNum = function () {
    if (event.keyCode === 8 || event.keyCode === 46) {
        return true;
    }
    if ($c.util.getKeyCode(event) >= 48 && $c.util.getKeyCode(event) <= 57) {
        return true;
    }
    if ($c.util.getKeyCode(event) >= 96 && $c.util.getKeyCode(event) <= 105) {
        return true;
    }
    return false;
};

/**
 * @method
 * @name excelDown
 * @description excel Down 처리
 * @param {String} tableID tableID
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function (tableID) {
    if (tableID.rows.length === 0) {
        await $c.win.alert("[계산하기]을 실행 후 다운로드 할 수 있습니다.");
        return;
    }
    $c.util.getComponent('dma_Cal16Req').set('excelData', tableID.outerHTML);
    scwin.form_frmISU_CD.method = "post";
    scwin.form_frmISU_CD.target = "_blank";
    scwin.form_frmISU_CD.action = "/bizspt/excelDown.jsp";
    await scwin.tx_fn_ExcelDown();
};
